// Billing settings (milestone M22; docs/adr/0025-billing.md, §12 of CLAUDE.md: no secrets of real
// services in the repository).
//
// - BILLING_PROVIDER: `test` (default; the local test provider, the only one CI uses) or `stripe`.
// - BILLING_TEST_WEBHOOK_SECRET: the HMAC key of the test provider's events (32+ characters,
//   generated by scripts/init-env.sh). Empty: derived from MAIL_SEAL_KEY, which the web process and
//   the worker share already, as INTERNAL_REVALIDATE_SECRET is (src/server/revalidate.ts).
// - STRIPE_SECRET_KEY, STRIPE_WEBHOOK_SECRET: only with BILLING_PROVIDER=stripe. The key must be a
//   Stripe *test* key (sk_test_…): a live key (sk_live_…), a restricted key or anything else is
//   refused at start (checkBillingSettings, called by src/instrumentation.ts through
//   src/server/auth/startup.ts and by the worker), and wherever the adapter is made.
//
// Messages name the setting, never its value.

import { createHmac } from 'node:crypto';

import { BILLING_PROVIDERS } from '../db/schema/common';
import type { BillingProviderName } from './types';

type Env = Record<string, string | undefined>;

const MIN_SECRET_LENGTH = 32;
const STRIPE_TEST_KEY = /^sk_test_[A-Za-z0-9]{8,}$/;
const STRIPE_WEBHOOK_SECRET = /^whsec_[A-Za-z0-9+/=]{8,}$/;

export class BillingConfigError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'BillingConfigError';
  }
}

/** The provider of this process: BILLING_PROVIDER, `test` when unset. */
export function billingProviderName(env: Env = process.env): BillingProviderName {
  const value = (env.BILLING_PROVIDER ?? '').trim() || 'test';
  if (!(BILLING_PROVIDERS as readonly string[]).includes(value)) throw new BillingConfigError('BILLING_PROVIDER must be "test" or "stripe".');
  return value as BillingProviderName;
}

/**
 * STRIPE_SECRET_KEY, when it is a Stripe test key. A live key is refused with its own message, so a
 * mistake is never silent; any other value (a restricted key, a publishable key) is refused too.
 */
export function stripeSecretKey(env: Env = process.env): string {
  const key = (env.STRIPE_SECRET_KEY ?? '').trim();
  if (!key) throw new BillingConfigError('STRIPE_SECRET_KEY is not set (BILLING_PROVIDER=stripe needs a Stripe test key, sk_test_…).');
  if (/^(sk|rk)_live_/.test(key)) throw new BillingConfigError('STRIPE_SECRET_KEY is a live key: only Stripe test keys (sk_test_…) are accepted; no real charge is ever made.');
  if (!STRIPE_TEST_KEY.test(key)) throw new BillingConfigError('STRIPE_SECRET_KEY must be a Stripe test secret key (sk_test_…).');
  return key;
}

/** STRIPE_WEBHOOK_SECRET (whsec_…), the signing secret of the Stripe test endpoint. */
export function stripeWebhookSecret(env: Env = process.env): string {
  const secret = (env.STRIPE_WEBHOOK_SECRET ?? '').trim();
  if (!STRIPE_WEBHOOK_SECRET.test(secret)) throw new BillingConfigError('STRIPE_WEBHOOK_SECRET must be the signing secret of a Stripe test webhook endpoint (whsec_…).');
  return secret;
}

/** The HMAC key of the test provider's events: its own setting, else derived from MAIL_SEAL_KEY. */
export function testWebhookSecret(env: Env = process.env): string {
  const own = (env.BILLING_TEST_WEBHOOK_SECRET ?? '').trim();
  if (own) {
    if (own.length < MIN_SECRET_LENGTH) throw new BillingConfigError(`BILLING_TEST_WEBHOOK_SECRET must be at least ${MIN_SECRET_LENGTH} characters.`);
    return own;
  }
  const seal = env.MAIL_SEAL_KEY;
  if (!seal || seal.length < MIN_SECRET_LENGTH) throw new BillingConfigError('BILLING_TEST_WEBHOOK_SECRET is not set, and MAIL_SEAL_KEY (its fallback) is missing.');
  return createHmac('sha256', seal).update('wingchunroots:billing-test-webhook:v1').digest('hex');
}

/**
 * Refuses a billing configuration that could charge for real or cannot verify its events: an
 * unknown provider; any STRIPE_SECRET_KEY that is not a test key, whatever the provider (a live key
 * in the environment is a mistake to stop at); with `stripe`, a missing key or webhook secret.
 */
export function checkBillingSettings(env: Env = process.env): BillingProviderName {
  const name = billingProviderName(env);
  if ((env.STRIPE_SECRET_KEY ?? '').trim() || name === 'stripe') stripeSecretKey(env);
  if (name === 'stripe') stripeWebhookSecret(env);
  return name;
}
